import { ThemeProvider } from '@mui/material/styles';
import Navbar from '../../components/Navbar';
import { theme } from '../../theme';
import { Box, Container, Grid, Tooltip, Typography } from '@mui/material';
import styled from '@emotion/styled';
import { workLists } from '../../storage';
import { useNavigate } from 'react-router-dom';
import './index.css';

const StyledImage = styled('img')(({ theme }) => ({
    width: '80%', // You can set the desired width
    height: '100%', // You can set the desired height

}));

export default function Work() {
    const navigate = useNavigate();

    const handleProject = (id: string | number) => {
        navigate(`/work/${id}`);
    }

    return (
        <ThemeProvider theme={theme}>
            <Navbar />
            <Container>

                <Box sx={{ paddingTop: 5, paddingBottom: 5 }}>
                    <Typography variant="h5" sx={{ textAlign: 'justify' }}>
                        Professional work and other client projects.
                    </Typography>
                </Box>


                {/* Stardibs, ipostmo, spottapark, athena, firesale, ride, autozone */}

                {/* Pragma/UBP - onboarding, external api, internal api, dev portal and dev portal api v2  - microservices*/}

                {/* Vertere/Sunlife - RJPHK API, ebao Facade API, DigiSig */}

                {/* Cloudstaff/Mumba - mumba */}
                <br />

                <Grid container rowSpacing={1} columnSpacing={{ xs: 1, sm: 2, md: 3 }}>
                    {workLists.map(work => {
                        return (
                            <Grid item xs={12} md={4} sx={{ textAlignLast: 'center' }}>
                                <Tooltip title=''>
                                    <Box className='work-list'>
                                        <StyledImage
                                            src={process.env.PUBLIC_URL + work.imgThumbUrl}
                                            alt="Hover Effect"
                                            onClick={() => handleProject(work.id)}
                                        />
                                        <Typography
                                            variant="body1"
                                            sx={{ textAlign: 'center', paddingTop: 1, paddingBottom: 1, cursor: 'pointer' }}
                                            onClick={() => handleProject(work.id)}
                                        >
                                            {work.title}
                                        </Typography>
                                    </Box>
                                </Tooltip>
                            </Grid>

                        )
                    })}

                </Grid>
            </Container>

        </ThemeProvider >
    );
}
