import { ThemeProvider } from '@mui/material/styles';
import Navbar from '../../components/Navbar';
import Header from './parts/header';
import Bio from './parts/bio';
import Projects from './parts/projects';
import Contact from '../contact/Contact';
import { theme } from '../../theme';

export default function Home() {
    return (
        <ThemeProvider theme={theme}>
            <Navbar />
            <Header description="Versatile Full Stack Developer adept at creating dynamic web applications with expertise in both front-end and back-end development." />
            <Bio
                overview="Hi, I'm John Michael. Nice to meet you."
                description="Experienced Full Stack Developer skilled in creating dynamic and responsive web applications. My journey into development began 9 years ago, and since then, I've been dedicated to mastering the intricacies of software engineering. Proficient in both front-end and back-end technologies, with a keen eye for user experience. Dedicated to delivering high-quality, scalable solutions to drive digital innovation."
            />
            <Projects overview="My Client projects and other professional work." />
            <Contact />
        </ThemeProvider >
    );
}
